settings.markdownTextFunction:
let name = data[0].entityName;
let type = data[0].Type;
let createdTime = moment(data[0]['Created time']).format("dd, MMMM, DD, yyyy HH:mm");

return `<div class="main-container flex flex-row justify-between">
            <div class="flex flex-1 flex-col justify-between">
                <span class="title">${name}</span>
                <span class="type">${type}</span>
            </div>
            <div class="flex flex-1 justify-end items-end gap-2">
                <span class="type">Created time</span>
                <span class="createdTime">${createdTime}</span>
            </div>
        </div>`;

